begin;
create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create type public.app_role as enum ('student','institution_owner','institution_staff','super_admin');
create type public.booking_status as enum ('pending','confirmed','reschedule_requested','rejected','cancelled','completed','no_show');
create table public.profiles (
 id uuid primary key references auth.users on delete cascade, full_name text not null default '', phone text not null default '', role public.app_role not null default 'student', avatar_path text,
 education_level text not null default '', email_notifications boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.institutions (
 id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references public.profiles, name text not null check(length(name) between 3 and 180), slug text not null unique check(slug ~ '^[a-z0-9-]+$'), description text not null default '', institution_type text not null check(institution_type in ('University','Private college','Government college','Deemed university')),
 official_email text not null, phone text not null default '', website_url text not null default '', address text not null default '', city text not null, state text not null, postal_code text not null default '', latitude numeric(9,6), longitude numeric(9,6), established_year integer,
 representative_name text not null default '', representative_designation text not null default '', verification_status text not null default 'pending' check(verification_status in ('pending','approved','rejected','suspended')), verification_notes text not null default '', cover_image_path text, published_at timestamptz,
 facilities text[] not null default '{}', hostel_details text not null default '', accreditation text not null default '', admission_process text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 search_document tsvector generated always as (to_tsvector('english', name || ' ' || city || ' ' || state || ' ' || description)) stored,
 check(published_at is null or verification_status='approved')
);
create unique index institution_email_unique on public.institutions(lower(official_email));
create index institution_search on public.institutions using gin(search_document);
create index institution_location on public.institutions(state,city);
create index institution_owner on public.institutions(owner_user_id);
create table public.institution_staff (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, user_id uuid not null references public.profiles on delete cascade, designation text not null default '', permissions text[] not null default array['bookings'], status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), unique(institution_id,user_id));
create table public.institution_verification_documents (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, storage_path text not null unique, document_type text not null, review_status text not null default 'pending', reviewed_by uuid references public.profiles, reviewed_at timestamptz, created_at timestamptz not null default now());
create table public.courses (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, name text not null, stream text not null, degree_type text not null default '', duration text not null default '', eligibility text not null default '', published_fee_amount numeric(12,2) check(published_fee_amount >= 0), fee_currency text not null default 'INR' check(fee_currency='INR'), intake_information text not null default '', description text not null default '', is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index course_discovery on public.courses(stream,published_fee_amount);
create index course_institution on public.courses(institution_id);
create table public.college_media (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, storage_path text not null unique, caption text not null default '', alt_text text not null, media_category text not null default 'campus', sort_order integer not null default 0, is_published boolean not null default false, created_at timestamptz not null default now());
create table public.institution_tours (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, tour_type text not null default 'virtual', tour_url text not null, title text not null, is_published boolean not null default false, created_at timestamptz not null default now());
create table public.student_interests (id uuid primary key default gen_random_uuid(), student_id uuid not null unique references public.profiles on delete cascade, preferred_streams text[] not null default '{}', preferred_states text[] not null default '{}', preferred_budget_min numeric(12,2), preferred_budget_max numeric(12,2), preferred_institution_types text[] not null default '{}', updated_at timestamptz not null default now(), check(preferred_budget_min >= 0), check(preferred_budget_max >= preferred_budget_min));
create table public.saved_institutions (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles on delete cascade, institution_id uuid not null references public.institutions on delete cascade, created_at timestamptz not null default now(), unique(student_id,institution_id));
create table public.counselling_slots (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, staff_user_id uuid not null references public.profiles, starts_at timestamptz not null, ends_at timestamptz not null, capacity integer not null default 1 check(capacity=1), status text not null default 'open' check(status in ('open','closed')), created_at timestamptz not null default now(), check(ends_at>starts_at), exclude using gist(staff_user_id with =, tstzrange(starts_at,ends_at,'[)') with &&) where(status='open'));
create table public.campus_visit_slots (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions on delete cascade, starts_at timestamptz not null, ends_at timestamptz not null, capacity integer not null check(capacity between 1 and 200), status text not null default 'open' check(status in ('open','closed')), created_at timestamptz not null default now(), check(ends_at>starts_at), unique(institution_id,starts_at));
create table public.counselling_bookings (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles, institution_id uuid not null references public.institutions, staff_user_id uuid not null references public.profiles, slot_id uuid not null references public.counselling_slots, starts_at timestamptz not null, ends_at timestamptz not null, student_enquiry text not null default '', status public.booking_status not null default 'pending', meeting_provider text, meeting_url text, institution_response text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(ends_at>starts_at));
create unique index counselling_one_active on public.counselling_bookings(slot_id,student_id) where(status in ('pending','confirmed','reschedule_requested'));
create table public.campus_visit_bookings (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles, institution_id uuid not null references public.institutions, slot_id uuid not null references public.campus_visit_slots, visitor_count integer not null check(visitor_count between 1 and 10), student_notes text not null default '', institution_response text not null default '', status public.booking_status not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index visit_one_active on public.campus_visit_bookings(slot_id,student_id) where(status in ('pending','confirmed','reschedule_requested'));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, title text not null, message text not null, notification_type text not null, related_entity_id uuid, read_at timestamptz, created_at timestamptz not null default now());
create table public.contact_enquiries (id uuid primary key default gen_random_uuid(), name text not null, email text not null, subject text not null, message text not null, institution_id uuid references public.institutions, student_id uuid references public.profiles, status text not null default 'new', created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_user_id uuid references public.profiles, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.course_categories (id uuid primary key default gen_random_uuid(), name text not null unique, enabled boolean not null default true);
insert into public.course_categories(name) values ('Engineering'),('Arts & Science'),('Medicine'),('Management'),('Agriculture'),('Law');
create table public.platform_settings (id boolean primary key default true check(id), cancellation_hours integer not null default 24 check(cancellation_hours between 0 and 168), retention_days integer not null default 365 check(retention_days>=30));
insert into public.platform_settings(id) values(true);
create table public.email_outbox (id uuid primary key default gen_random_uuid(), notification_id uuid unique references public.notifications on delete cascade, recipient text not null, subject text not null, body text not null, attempts integer not null default 0, available_at timestamptz not null default now(), locked_until timestamptz, sent_at timestamptz, created_at timestamptz not null default now());
create table public.rate_limits (key text primary key, hits integer not null, expires_at timestamptz not null);
create table public.account_deletion_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles, status text not null default 'pending', created_at timestamptz not null default now());

create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='super_admin') $$;
create function public.can_manage(i uuid, permission text default 'profile') returns boolean language sql stable security definer set search_path='' as $$ select public.is_admin() or exists(select 1 from public.institutions where id=i and owner_user_id=auth.uid()) or exists(select 1 from public.institution_staff where institution_id=i and user_id=auth.uid() and status='active' and permission=any(permissions)) $$;
create function public.is_public(i uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.institutions where id=i and verification_status='approved' and published_at is not null) $$;
create function public.on_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),120)); return new; end $$;
create trigger create_profile after insert on auth.users for each row execute function public.on_signup();

do $$ declare t text; begin foreach t in array array['profiles','institutions','institution_staff','institution_verification_documents','courses','college_media','institution_tours','student_interests','saved_institutions','counselling_slots','campus_visit_slots','counselling_bookings','campus_visit_bookings','notifications','contact_enquiries','audit_logs','course_categories','platform_settings','email_outbox','rate_limits','account_deletion_requests'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.profiles,public.institutions,public.institution_staff,public.institution_verification_documents,public.courses,public.college_media,public.institution_tours,public.student_interests,public.saved_institutions,public.counselling_slots,public.campus_visit_slots,public.counselling_bookings,public.campus_visit_bookings,public.notifications,public.contact_enquiries,public.audit_logs,public.course_categories,public.platform_settings,public.account_deletion_requests to authenticated;
grant select on public.institutions,public.courses,public.college_media,public.institution_tours,public.counselling_slots,public.campus_visit_slots,public.course_categories to anon;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy institution_read on public.institutions for select using(public.is_public(id) or public.can_manage(id));
create policy staff_read on public.institution_staff for select to authenticated using(user_id=auth.uid() or public.can_manage(institution_id,'staff'));
create policy docs_read on public.institution_verification_documents for select to authenticated using(public.can_manage(institution_id,'documents'));
create policy courses_read on public.courses for select using((is_published and public.is_public(institution_id)) or public.can_manage(institution_id,'courses'));
create policy media_read on public.college_media for select using((is_published and public.is_public(institution_id)) or public.can_manage(institution_id,'media'));
create policy tours_read on public.institution_tours for select using((is_published and public.is_public(institution_id)) or public.can_manage(institution_id,'media'));
create policy interests_read on public.student_interests for select to authenticated using(student_id=auth.uid());
create policy saved_read on public.saved_institutions for select to authenticated using(student_id=auth.uid());
create policy counselling_slots_read on public.counselling_slots for select using((public.is_public(institution_id) and status='open' and starts_at>now()) or public.can_manage(institution_id,'bookings'));
create policy visit_slots_read on public.campus_visit_slots for select using((public.is_public(institution_id) and status='open' and starts_at>now()) or public.can_manage(institution_id,'bookings'));
create policy counselling_read on public.counselling_bookings for select to authenticated using(student_id=auth.uid() or public.can_manage(institution_id,'bookings'));
create policy visits_read on public.campus_visit_bookings for select to authenticated using(student_id=auth.uid() or public.can_manage(institution_id,'bookings'));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy enquiries_read on public.contact_enquiries for select to authenticated using(student_id=auth.uid() or public.is_admin() or public.can_manage(institution_id,'enquiries'));
create policy audit_read on public.audit_logs for select to authenticated using(public.is_admin());
create policy category_read on public.course_categories for select using(enabled or public.is_admin());
create policy settings_read on public.platform_settings for select to authenticated using(true);
create policy deletion_read on public.account_deletion_requests for select to authenticated using(user_id=auth.uid() or public.is_admin());

do $$ declare t text; begin foreach t in array array['institution_staff','institution_verification_documents','college_media','institution_tours','counselling_slots','campus_visit_slots','counselling_bookings','campus_visit_bookings','contact_enquiries'] loop execute format('create index on public.%I(institution_id)',t); end loop; foreach t in array array['counselling_bookings','campus_visit_bookings'] loop execute format('create index on public.%I(student_id,created_at desc)',t); execute format('create index on public.%I(slot_id,status)',t); end loop; end $$;
create index on public.notifications(user_id,created_at desc);
create index on public.email_outbox(available_at) where sent_at is null;
create index on public.institution_staff(user_id);
commit;
